import csv
import io


def parse_csv(raw_csv: str):
    if not raw_csv:
        return {"columns": [], "rows": []}

    if raw_csv.startswith("\ufeff"):
        raw_csv = raw_csv[1:]

    previous_limit = csv.field_size_limit()
    try:
        if len(raw_csv) > previous_limit:
            csv.field_size_limit(len(raw_csv))
        reader = csv.reader(io.StringIO(raw_csv, newline=""), skipinitialspace=True)
        records = [[value.strip(" \t") for value in row] for row in reader]
    finally:
        csv.field_size_limit(previous_limit)

    if not records:
        return {"columns": [], "rows": []}

    columns = records[0]
    if columns and columns[0].startswith("#"):
        columns[0] = columns[0][1:].strip(" \t")

    rows = records[1:]
    width = max([6, len(columns)] + [len(row) for row in rows])

    used = set(columns)
    while len(columns) < width:
        base = "column_{}".format(len(columns) + 1)
        name = base
        suffix = 2
        while name in used:
            name = "{}_{}".format(base, suffix)
            suffix += 1
        columns.append(name)
        used.add(name)

    for row in rows:
        row.extend([""] * (width - len(row)))

    return {"columns": columns, "rows": rows}
